#!/usr/bin/env bash
# compiler-release-dependencies.sh's and compiler-konan-dependencies.sh's own test, over made-up zips and dependencies,
# in a made-up home. stage must copy a home's dependencies into the layout unpack takes, keeping only what unpack
# keeps, so unpack of its entry warns of nothing, and fail on a name or a link unpack would refuse. unpack must put a
# zip of stage's paths where the build looks for them, laying out the runner's binaryen archive as its releases are;
# must drop a Gradle file that isn't the bytes the verification metadata pins at
# their SHA-1's path, and go on; must take entries of any mode, and clean up after them; must refuse whole, putting
# nothing anywhere, a zip with a name that climbs out, an absolute name, a name at a path stage doesn't make, a name
# twice, a link, more entries or bytes than its limits, an entry of more bytes than it declares, or that isn't a zip;
# must drop a toolchain or Kotlin/Native archive whose name and SHA-256 aren't pinned, and go on; must take away what
# it put in place where a step fails, in a $(...) too; and must take the test's own pins only in the test. check must
# pass the dependencies the list pins, and fail one it doesn't, or a list that pins nothing. fetch must put in
# Kotlin/Native's cache only an archive with the pinned SHA-256, kept or fetched again, and fail where it has none. Run
# by compiler-release.yml's dry run, in build, on macOS as build unpacks there.
#   compiler-release-dependencies-test.sh
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
work=$(mktemp -d "${RUNNER_TEMP:-${TMPDIR:-/tmp}}/compiler-release-dependencies-test.XXXXXX")
trap 'rm -rf "$work"' EXIT
fail() { echo "compiler-release-dependencies-test: $*" >&2; exit 1; }

# Every file zipped writes is "a dependency\n": Gradle's files sit in its SHA-1's directory, as Gradle lays them out.
sha1=$(printf 'a dependency\n' | shasum -a 1 | cut -d' ' -f1)
sha256=$(printf 'a dependency\n' | shasum -a 256 | cut -d' ' -f1)
jar=gradle/org.example/lib/1.0/$sha1/lib-1.0.jar
binaryen=gradle/com.github.webassembly/binaryen/123/$sha1/binaryen-123-arm64-macos.tar.gz
good=("$jar" "$binaryen" toolchain/gradle-9.6.1-bin.zip konan/llvm-19-aarch64-macos-essentials-79.tar.gz)
# What unpack checks against, in place of the repository's: this runner's binaryen platform, which the test names, and
# pins of zipped's bytes: verification metadata for the jar and for binaryen's archive on that platform and another,
# and the JDK's, Gradle's and Kotlin/Native's archives. unpack takes them only with COMPILER_RELEASE_DEPENDENCIES_TEST
# set.
export COMPILER_RELEASE_DEPENDENCIES_TEST=true COMPILER_BINARYEN_PLATFORM=arm64-macos
other_binaryen="${binaryen%-arm64-macos.tar.gz}-x86_64-linux.tar.gz"
export COMPILER_PINS="$work/pins"
mkdir -p "$COMPILER_PINS/wrapper"
printf '# made up\nversion=21.0.13+9\nsha256.mac-aarch64=%s\nsha256.windows-x64=%s\n' "$sha256" "$sha256" > "$COMPILER_PINS/pinned-jdk.properties"
printf 'distributionSha256Sum=%s\ndistributionUrl=https\\://services.gradle.org/distributions/gradle-9.6.1-bin.zip\n' "$sha256" > "$COMPILER_PINS/wrapper/gradle-wrapper.properties"
printf '# made up\n%s https://download.example/native/llvm-19-aarch64-macos-essentials-79.tar.gz\n' "$sha256" > "$COMPILER_PINS/kotlin-native-dependencies.txt"
cat > "$COMPILER_PINS/verification-metadata.xml" <<XML
<?xml version="1.0" encoding="UTF-8"?>
<verification-metadata xmlns="https://schema.gradle.org/dependency-verification">
   <components>
      <component group="com.github.webassembly" name="binaryen" version="123">
         <artifact name="${binaryen##*/}">
            <sha256 value="$sha256" origin="Generated by Gradle"/>
         </artifact>
         <artifact name="${other_binaryen##*/}">
            <sha256 value="$sha256" origin="Generated by Gradle"/>
         </artifact>
      </component>
      <component group="org.example" name="lib" version="1.0">
         <artifact name="${jar##*/}">
            <sha256 value="$sha256" origin="Generated by Gradle"/>
         </artifact>
         <artifact name="lib 1.0.jar">
            <sha256 value="$sha256" origin="Generated by Gradle"/>
         </artifact>
      </component>
   </components>
</verification-metadata>
XML

# A zip of <entry>s: <path> a file of a few bytes, <path>/ a directory, link|<path>|<target> a link.
zipped() {
    local out="$1"; shift
    python3 -I - "$out" "$@" <<'PY'
import sys, zipfile
out, entries = sys.argv[1], sys.argv[2:]
with zipfile.ZipFile(out, "w") as z:
    for entry in entries:
        kind, _, rest = entry.partition("|")
        if kind == "link":
            path, target = rest.split("|")
            info = zipfile.ZipInfo(path)
            info.create_system = 3
            info.external_attr = 0o120777 << 16
            z.writestr(info, target)
        else:
            info = zipfile.ZipInfo(entry)
            info.create_system = 3
            info.external_attr = (0o40755 if entry.endswith("/") else 0o100644) << 16
            z.writestr(info, "" if entry.endswith("/") else "a dependency\n")
PY
}

# A zip of <dir>'s files, named from <dir>, as upload-artifact zips a directory.
zipdir() {
    python3 -I - "$1" "$2" <<'PY2'
import os, sys, zipfile
out, root = sys.argv[1], sys.argv[2]
with zipfile.ZipFile(out, "w") as z:
    for top, _, files in os.walk(root):
        for f in files:
            path = os.path.join(top, f)
            z.write(path, os.path.relpath(path, root))
PY2
}

# unpack <zip> in a home of its own: its output, and what it put in the home.
unpacked() {
    local zip="$1" home="$work/home-${RANDOM}${RANDOM}"
    mkdir "$home"
    HOME="$home" "$here/compiler-release-dependencies.sh" unpack "$zip" > "$home.out" 2>&1 || fail "unpack of $zip exited $?: $(cat "$home.out")"
    UNPACK_OUT=$(cat "$home.out")
    UNPACKED=$(cd "$home" && find . -type f | sort)
}

zipped "$work/good.zip" gradle/ "${good[@]}"
unpacked "$work/good.zip"
for want in ./.gradle/caches/modules-2/files-2.1/${jar#gradle/} ./.gradle/caches/modules-2/files-2.1/${binaryen#gradle/} \
    ./.cache/drivine-pinned-toolchain/gradle-9.6.1-bin.zip ./.cache/drivine-konan-dependencies/llvm-19-aarch64-macos-essentials-79.tar.gz \
    ./.cache/drivine-binaryen/version_123/binaryen-version_123-arm64-macos.tar.gz; do
    grep -qxF "$want" <<< "$UNPACKED" || fail "unpack of stage's paths didn't put $want: $UNPACKED"
done
(( $(wc -l <<< "$UNPACKED") == 5 )) || fail "unpack put more than stage's paths: $UNPACKED"
echo "unpack puts stage's paths, and binaryen's archive as its releases are"
python3 -I - "$work/other-binaryen.zip" "$binaryen" <<'PY2'
import sys, zipfile
with zipfile.ZipFile(sys.argv[1], "w") as z:
    info = zipfile.ZipInfo(sys.argv[2])
    info.create_system = 3
    info.external_attr = 0o100644 << 16
    z.writestr(info, "another binaryen")
PY2
unpacked "$work/other-binaryen.zip"
[[ -z "$UNPACKED" ]] || fail "unpack kept, or laid out, a binaryen archive the metadata doesn't pin: $UNPACKED"
[[ "$UNPACK_OUT" == *"::warning::1 of the release dependencies' Gradle files aren't the bytes"* ]] || fail "unpack didn't say it dropped binaryen's archive: $UNPACK_OUT"
echo "unpack drops, and doesn't lay out, a binaryen archive of bytes the verification metadata doesn't pin"
zipped "$work/other-platform.zip" "$other_binaryen"
unpacked "$work/other-platform.zip"
[[ "$UNPACKED" == "./.gradle/caches/modules-2/files-2.1/${other_binaryen#gradle/}" ]] || fail "unpack laid out another platform's binaryen archive: $UNPACKED"
echo "unpack lays out only this runner's binaryen archive"
zipped "$work/no-binaryen.zip" "$jar"
unpacked "$work/no-binaryen.zip"
[[ "$UNPACKED" == "./.gradle/caches/modules-2/files-2.1/${jar#gradle/}" ]] || fail "unpack of a zip without binaryen put $UNPACKED"
echo "unpack takes a zip without binaryen, or without toolchain or Kotlin/Native archives"

# Gradle's files that would fail every release: other bytes at the real path (Gradle takes a file at its SHA-1's path
# unchecked), the pinned bytes at another SHA-1's path, and a file the metadata doesn't name. Each is dropped, the rest
# is kept, and unpack goes on.
python3 -I - "$work/planted.zip" "$jar" "${jar%/lib-1.0.jar}/lib-1.0-sources.jar" "gradle/org.example/lib/1.0/0123456789abcdef0123456789abcdef01234567/lib-1.0.pom" "$binaryen" <<'PY2'
import sys, zipfile
out, planted, unnamed, elsewhere, kept = sys.argv[1:]
with zipfile.ZipFile(out, "w") as z:
    for name, data in ((planted, "planted\n"), (unnamed, "a dependency\n"), (elsewhere, "a dependency\n"), (kept, "a dependency\n")):
        info = zipfile.ZipInfo(name)
        info.create_system = 3
        info.external_attr = 0o100644 << 16
        z.writestr(info, data)
PY2
unpacked "$work/planted.zip"
[[ "$UNPACKED" == "$(printf '%s\n' "./.cache/drivine-binaryen/version_123/binaryen-version_123-arm64-macos.tar.gz" "./.gradle/caches/modules-2/files-2.1/${binaryen#gradle/}" | sort)" ]] || fail "unpack kept a Gradle file that isn't the pinned bytes at their SHA-1's path: $UNPACKED"
[[ "$UNPACK_OUT" == *"::warning::3 of the release dependencies' Gradle files aren't the bytes"* ]] || fail "unpack didn't say it dropped three files: $UNPACK_OUT"
echo "unpack drops a Gradle file of other bytes, at another SHA-1's path, or that the metadata doesn't name"
# The toolchain and Kotlin/Native archives: kept where their names and SHA-256s are pinned (the JDK's, of any platform
# pinned, as the toolchain action names it), dropped where their bytes, name or platform aren't, and unpack goes on.
python3 -I - "$work/archives.zip" <<'PY2'
import sys, zipfile
with zipfile.ZipFile(sys.argv[1], "w") as z:
    for name, data in (("toolchain/temurin-21.0.13+9-mac-aarch64.tar.gz", "a dependency\n"),
                       ("toolchain/temurin-21.0.13+9-windows-x64.zip", "a dependency\n"),
                       ("toolchain/gradle-9.6.1-bin.zip", "planted\n"),
                       ("toolchain/temurin-21.0.13+9-linux-x64.tar.gz", "a dependency\n"),
                       ("toolchain/temurin-21.0.13+9-windows-x64.tar.gz", "a dependency\n"),
                       ("toolchain/filler", "a dependency\n"),
                       ("konan/llvm-19-aarch64-macos-essentials-79.tar.gz", "a dependency\n"),
                       ("konan/lldb-4-macos.tar.gz", "a dependency\n")):
        info = zipfile.ZipInfo(name)
        info.create_system = 3
        info.external_attr = 0o100644 << 16
        z.writestr(info, data)
PY2
unpacked "$work/archives.zip"
[[ "$UNPACKED" == "$(printf '%s\n' ./.cache/drivine-konan-dependencies/llvm-19-aarch64-macos-essentials-79.tar.gz "./.cache/drivine-pinned-toolchain/temurin-21.0.13+9-mac-aarch64.tar.gz" "./.cache/drivine-pinned-toolchain/temurin-21.0.13+9-windows-x64.zip" | sort)" ]] || fail "unpack kept a toolchain or Kotlin/Native archive its pins don't name: $UNPACKED"
[[ "$UNPACK_OUT" == *"::warning::5 of the release dependencies' toolchain and Kotlin/Native archives aren't ones pinned"* ]] || fail "unpack didn't say it dropped five archives: $UNPACK_OUT"
echo "unpack drops a toolchain or Kotlin/Native archive whose name or SHA-256 its pins don't name"
# Without COMPILER_RELEASE_DEPENDENCIES_TEST, the repository's own pins, which name no org.example, nor these bytes.
home="$work/home-untested"
mkdir "$home"
HOME="$home" COMPILER_RELEASE_DEPENDENCIES_TEST= "$here/compiler-release-dependencies.sh" unpack "$work/good.zip" > "$home.out" 2>&1 || fail "unpack exited $?: $(cat "$home.out")"
[[ -z "$(cd "$home" && find . -type f)" ]] || fail "unpack took the test's pins outside the test: $(cd "$home" && find . -type f)"
[[ "$(cat "$home.out")" != *"is refused"* ]] || fail "unpack refused the zip outside the test, rather than check it against the repository's pins: $(cat "$home.out")"
echo "unpack takes the test's pins only in the test"

# Modes that leave a file unreadable or a directory unlistable: unpack makes them the owner's, checks them as any, and
# its own clean-up still removes them.
python3 -I - "$work/modes.zip" "$jar" <<'PY2'
import sys, zipfile
out, jar = sys.argv[1:]
with zipfile.ZipFile(out, "w") as z:
    d = zipfile.ZipInfo(jar.rsplit("/", 1)[0] + "/")
    d.create_system = 3
    d.external_attr = 0o40000 << 16
    z.writestr(d, "")
    f = zipfile.ZipInfo(jar)
    f.create_system = 3
    f.external_attr = 0o100000 << 16
    z.writestr(f, "a dependency\n")
PY2
mkdir "$work/temp"
RUNNER_TEMP="$work/temp" unpacked "$work/modes.zip"
[[ "$UNPACKED" == "./.gradle/caches/modules-2/files-2.1/${jar#gradle/}" ]] || fail "unpack of entries of mode 000 put $UNPACKED: $UNPACK_OUT"
[[ -z "$(ls -A "$work/temp")" ]] || fail "unpack left its work behind: $(ls -A "$work/temp")"
echo "unpack takes entries of mode ---------- and d---------, and cleans up after them"

# Too many entries, or too many bytes: refused before anything is unpacked.
COMPILER_MAX_ENTRIES=3 unpacked "$work/good.zip"
[[ "$UNPACK_OUT" == *"is refused"*"more than 3"* && -z "$UNPACKED" ]] || fail "unpack took more entries than its limit: $UNPACK_OUT"
COMPILER_MAX_BYTES=20 unpacked "$work/good.zip"
[[ "$UNPACK_OUT" == *"is refused"*"more than 20"* && -z "$UNPACKED" ]] || fail "unpack took more bytes than its limit: $UNPACK_OUT"
echo "unpack refuses a zip of more entries or bytes than its limits"

# A step that fails once some of the zip is in place: refused, and what was put in place is taken away. Here the
# toolchain archives can't go where they go, after Gradle's files have.
home="$work/home-blocked"
mkdir "$home"
echo "not a directory" > "$home/.cache"
HOME="$home" "$here/compiler-release-dependencies.sh" unpack "$work/good.zip" > "$home.out" 2>&1 || fail "unpack exited $?: $(cat "$home.out")"
[[ "$(cat "$home.out")" == *"is refused"*"failed"* ]] || fail "unpack didn't refuse where a step failed: $(cat "$home.out")"
[[ "$(cd "$home" && find . -type f)" == "./.cache" && ! -e "$home/.gradle/caches/modules-2/files-2.1" ]] || fail "unpack left some of the zip in place: $(cd "$home" && find . -type f)"
echo "unpack refuses, and takes away what it put in place, where a step fails"
# A step in a $(...) that fails once the zip is in place: the ERR trap runs in that subshell, and unpack must still
# refuse, not go on. Here basename fails on binaryen's archive, as unpack lays it out (and only there: python3 can be a
# script that runs basename).
mkdir -p "$work/failing-bin"
printf '#!/bin/sh\ncase "$*" in *binaryen-123-*) exit 1 ;; esac\nexec /usr/bin/basename "$@"\n' > "$work/failing-bin/basename"
chmod +x "$work/failing-bin/basename"
PATH="$work/failing-bin:$PATH" unpacked "$work/good.zip"
[[ "$UNPACK_OUT" == *"is refused"*"failed"* && -z "$UNPACKED" ]] || fail "unpack went on where a step in a \$(...) failed: $UNPACK_OUT: $UNPACKED"
echo "unpack refuses, and takes away what it put in place, where a step in a \$(...) fails"

# An entry that declares fewer bytes than its data holds: unzip would write all its data, past the limit; unpack writes
# no more than declared, and refuses it on its CRC.
python3 -I - "$work/lying.zip" "$jar" <<'PY2'
import struct, sys, zipfile
out, name = sys.argv[1:]
with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
    info = zipfile.ZipInfo(name)
    info.create_system = 3
    info.external_attr = 0o100644 << 16
    info.compress_type = zipfile.ZIP_DEFLATED
    z.writestr(info, b"\0" * (8 << 20))
data = bytearray(open(out, "rb").read())
central = data.find(b"PK\x01\x02")
data[22:26] = data[central + 24:central + 28] = struct.pack("<I", 13)
open(out, "wb").write(data)
PY2
unpacked "$work/lying.zip"
[[ "$UNPACK_OUT" == *"is refused"*"can't be unpacked"* && -z "$UNPACKED" ]] || fail "unpack took an entry of more bytes than it declares: $UNPACK_OUT: $UNPACKED"
echo "refused: an entry of more bytes than it declares"

# stage, from a made-up home: Gradle's files, the toolchain archives, and Kotlin/Native's archives but nothing else of
# its, into what unpack takes whole; and of those only what unpack keeps, so unpack of its entry warns of nothing. It
# leaves out a POM the metadata doesn't name (as Gradle downloads, and doesn't record, the POM of a module published
# with Gradle's module metadata), and a toolchain archive the pins don't name.
home="$work/stage-home"
jardir="$home/.gradle/caches/modules-2/files-2.1/$(dirname "${jar#gradle/}")"
mkdir -p "$jardir" "$home/.cache/drivine-pinned-toolchain" "$home/.cache/drivine-konan-dependencies"
printf 'a dependency\n' > "$jardir/${jar##*/}"
printf 'a dependency\n' > "$home/.cache/drivine-pinned-toolchain/gradle-9.6.1-bin.zip"
printf 'a dependency\n' > "$home/.cache/drivine-konan-dependencies/llvm-19-aarch64-macos-essentials-79.tar.gz"
echo partial > "$home/.cache/drivine-konan-dependencies/llvm.part"
printf 'a dependency\n' > "$jardir/lib-1.0.pom"
printf 'a dependency\n' > "$home/.cache/drivine-pinned-toolchain/gradle-9.5-bin.zip"
HOME="$home" "$here/compiler-release-dependencies.sh" stage "$work/staged" > "$work/stage.out" 2>&1 || fail "stage exited $?: $(cat "$work/stage.out")"
staged=$(cd "$work/staged" && find . -type f | sort)
[[ "$staged" == "$(printf '%s\n' ./${jar} ./konan/llvm-19-aarch64-macos-essentials-79.tar.gz ./toolchain/gradle-9.6.1-bin.zip | sort)" ]] || fail "stage put $staged"
zipdir "$work/staged.zip" "$work/staged"
unpacked "$work/staged.zip"
(( $(wc -l <<< "$UNPACKED") == 3 )) || fail "unpack of stage's zip put $UNPACKED: $UNPACK_OUT"
[[ "$UNPACK_OUT" != *"::warning::"* ]] || fail "unpack of stage's zip warned: $UNPACK_OUT"
grep -q "Left out 1 of Gradle's files.*lib-1.0.pom" "$work/stage.out" || fail "stage didn't say it left out the POM: $(cat "$work/stage.out")"
grep -q "Left out 1 toolchain.*gradle-9.5-bin.zip" "$work/stage.out" || fail "stage didn't say it left out the archive: $(cat "$work/stage.out")"
[[ "$(cat "$work/stage.out")" != *"::warning::"* ]] || fail "stage warned: $(cat "$work/stage.out")"
echo "stage copies the dependencies, and of them only what unpack keeps, so unpack of its entry warns of nothing"
# A name unpack refuses, of a file the metadata pins (one it doesn't pin, stage leaves out).
printf 'a dependency\n' > "$jardir/lib 1.0.jar"
if HOME="$home" "$here/compiler-release-dependencies.sh" stage "$work/staged-odd" > "$work/stage.out" 2>&1; then
    fail "stage took a name unpack refuses"
fi
grep -q "::error::.*lib 1.0.jar isn't a name unpack takes" "$work/stage.out" || fail "stage didn't name the file: $(cat "$work/stage.out")"
rm "$jardir/lib 1.0.jar"
ln -s "$home/.cache" "$jardir/lib-1.1.jar"
if HOME="$home" "$here/compiler-release-dependencies.sh" stage "$work/staged-link" > "$work/stage.out" 2>&1; then
    fail "stage took a link"
fi
grep -q "::error::.*lib-1.1.jar isn't a plain file" "$work/stage.out" || fail "stage didn't name the link: $(cat "$work/stage.out")"
echo "stage fails on a name, or a link, unpack would refuse"

refused() {
    local what="$1" zip="$2" expect="$3"
    unpacked "$zip"
    [[ "$UNPACK_OUT" == *"::warning::The release dependencies' zip is refused"*"$expect"* ]] || fail "$what: not refused for \"$expect\": $UNPACK_OUT"
    [[ -z "$UNPACKED" ]] || fail "$what: refused, but put $UNPACKED"
    echo "refused: $what"
}
zipped "$work/climbs.zip" "${good[@]}" gradle/org.example/lib/1.0/0123456789abcdef0123456789abcdef01234567/../../../../../../.bashrc
refused "a name that climbs out" "$work/climbs.zip" "isn't a path stage makes"
zipped "$work/dot.zip" "${good[@]}" gradle/org.example/lib/1.0/0123456789abcdef0123456789abcdef01234567/.
refused "a . part" "$work/dot.zip" "isn't a path stage makes"
zipped "$work/absolute.zip" "${good[@]}" /tmp/compiler-release-dependencies-test
refused "an absolute name" "$work/absolute.zip" "isn't a path stage makes"
zipped "$work/init.zip" "${good[@]}" init.d/evil.gradle
refused "a path outside stage's" "$work/init.zip" "init.d/evil.gradle"
zipped "$work/shallow.zip" "${good[@]}" gradle/lib-1.0.jar
refused "a file of Gradle's at a path Gradle doesn't make" "$work/shallow.zip" "gradle/lib-1.0.jar"
zipped "$work/konan.zip" "${good[@]}" konan/llvm.sh
refused "a Kotlin/Native file that isn't an archive" "$work/konan.zip" "konan/llvm.sh"
zipped "$work/link.zip" "${good[@]}" "link|gradle/org.example/lib/1.0/0123456789abcdef0123456789abcdef01234567/lib-1.1.jar|$HOME/.bashrc"
refused "a link" "$work/link.zip" "isn't a plain file or directory"
python3 -I - "$work/twice.zip" "$jar" <<'PY2'
import sys, warnings, zipfile
warnings.simplefilter("ignore")
with zipfile.ZipFile(sys.argv[1], "w") as z:
    z.writestr(sys.argv[2], "the dependency")
    z.writestr(sys.argv[2], "another")
PY2
refused "a name twice" "$work/twice.zip" "twice"
zipped "$work/newline.zip" "${good[@]}" "$(printf '%s\n%s' "$jar" "${jar%.jar}-2.jar")"
refused "a name with a newline" "$work/newline.zip" "isn't a path stage makes"
zipped "$work/empty.zip"
refused "an empty zip" "$work/empty.zip" "nothing of it is used"
echo "not a zip" > "$work/not.zip"
refused "a file that isn't a zip" "$work/not.zip" "unzip can't list it"

# check: the dependencies Kotlin/Native unpacked, against a list of two.
list="$work/pins.txt"
{
    echo "# made up"
    echo "$(printf 'a%.0s' {1..64}) https://download.example/native/llvm-19-aarch64-macos-essentials-79.tar.gz"
    echo "$(printf 'b%.0s' {1..64}) https://download.example/native/libffi-3.3-1-macos-arm64.tar.gz"
} > "$list"
konan="$work/konan"
mkdir -p "$konan/dependencies/cache" "$konan/dependencies/llvm-19-aarch64-macos-essentials-79"
touch "$konan/dependencies/.extracted" "$konan/dependencies/cache/.lock"
KONAN_DATA_DIR="$konan" "$here/compiler-konan-dependencies.sh" check "$list" > "$work/check.out" 2>&1 || fail "check refused a pinned dependency: $(cat "$work/check.out")"
echo "check passes a pinned dependency"
mkdir "$konan/dependencies/lldb-4-macos"
if KONAN_DATA_DIR="$konan" "$here/compiler-konan-dependencies.sh" check "$list" > "$work/check.out" 2>&1; then
    fail "check passed a dependency the list doesn't pin"
fi
grep -q 'unpacked lldb-4-macos' "$work/check.out" || fail "check didn't name the dependency it refused: $(cat "$work/check.out")"
echo "check fails a dependency the list doesn't pin"
echo "$(printf 'c%.0s' {1..63}) https://download.example/native/x.tar.gz" >> "$list"
if KONAN_DATA_DIR="$konan" "$here/compiler-konan-dependencies.sh" check "$list" > "$work/check.out" 2>&1; then
    fail "check took a list with a malformed line"
fi
echo "check refuses a malformed list"
echo "# nothing" > "$list"
if KONAN_DATA_DIR="$konan" "$here/compiler-konan-dependencies.sh" check "$list" > "$work/check.out" 2>&1; then
    fail "check took a list that pins nothing"
fi
grep -q 'pins nothing' "$work/check.out" || fail "check didn't say the list pins nothing: $(cat "$work/check.out")"
echo "check refuses a list that pins nothing"
rm -rf "$konan/dependencies/lldb-4-macos"
printf '%s https://download.example/native/llvm-19-aarch64-macos-essentials-79.tar.gz' "$(printf 'a%.0s' {1..64})" > "$list"
KONAN_DATA_DIR="$konan" "$here/compiler-konan-dependencies.sh" check "$list" > "$work/check.out" 2>&1 || fail "check didn't read a last line without a newline: $(cat "$work/check.out")"
echo "check reads a last line without a newline"

# fetch: a kept archive whose SHA-256 is the pinned one goes into Kotlin/Native's cache; a kept archive with another is
# fetched again, and where it can't be, fetch fails and puts nothing of it there. curl is a stand-in that serves
# $SERVE, or fails as an outage does, so nothing is fetched and archive.sh's retries don't wait.
mkdir -p "$work/bin"
cat > "$work/bin/curl" <<'SH'
#!/usr/bin/env bash
out=
while (( $# )); do [[ "$1" == -o ]] && { out="$2"; shift; }; shift; done
[[ -n "${SERVE:-}" && -n "$out" ]] || exit 22
cp "$SERVE" "$out"
SH
chmod +x "$work/bin/curl"
printf 'the llvm archive\n' > "$work/llvm.tar.gz"
llvm_sha=$(shasum -a 256 "$work/llvm.tar.gz" | cut -d' ' -f1)
echo "$llvm_sha https://download.example/native/llvm-19-aarch64-macos-essentials-79.tar.gz" > "$list"
fetch_home="$work/fetch-home" fetch_konan="$work/fetch-konan"
kept_llvm="$fetch_home/.cache/drivine-konan-dependencies/llvm-19-aarch64-macos-essentials-79.tar.gz"
cached_llvm="$fetch_konan/dependencies/cache/llvm-19-aarch64-macos-essentials-79.tar.gz"
fetch() { HOME="$fetch_home" KONAN_DATA_DIR="$fetch_konan" PATH="$work/bin:$PATH" "$here/compiler-konan-dependencies.sh" fetch "$list" > "$work/fetch.out" 2>&1; }
mkdir -p "$(dirname "$kept_llvm")"
cp "$work/llvm.tar.gz" "$kept_llvm"
fetch || fail "fetch refused a kept archive with the pinned SHA-256: $(cat "$work/fetch.out")"
cmp -s "$cached_llvm" "$work/llvm.tar.gz" || fail "fetch didn't put the kept archive in Kotlin/Native's cache"
echo "fetch takes a kept archive with the pinned SHA-256"
rm -rf "$fetch_konan"
echo "another llvm" > "$kept_llvm"
if fetch; then
    fail "fetch took a kept archive with another SHA-256, which it couldn't fetch again"
fi
[[ ! -e "$cached_llvm" && ! -e "$kept_llvm" ]] || fail "fetch refused the kept archive, but left it, or put it in Kotlin/Native's cache"
echo "another llvm" > "$kept_llvm"
SERVE="$work/llvm.tar.gz" fetch || fail "fetch didn't fetch again a kept archive with another SHA-256: $(cat "$work/fetch.out")"
cmp -s "$cached_llvm" "$work/llvm.tar.gz" || fail "fetch put another archive than the pinned one in Kotlin/Native's cache"
echo "another" > "$work/llvm-other.tar.gz"
rm -rf "$fetch_konan" "$kept_llvm"
if SERVE="$work/llvm-other.tar.gz" fetch; then
    fail "fetch took a fetched archive with another SHA-256"
fi
[[ ! -e "$cached_llvm" ]] || fail "fetch put a fetched archive with another SHA-256 in Kotlin/Native's cache"
echo "fetch refuses a kept or fetched archive with another SHA-256, and fetches the pinned one again"
